CREATE TABLE IF NOT EXISTS project_milestones (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,project_id BIGINT UNSIGNED NOT NULL,name VARCHAR(180) NOT NULL,description TEXT NULL,due_date DATE NULL,status ENUM('pending','in_progress','completed','on_hold') NOT NULL DEFAULT 'pending',sort_order INT NOT NULL DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,INDEX(project_id),CONSTRAINT fk_milestone_project FOREIGN KEY(project_id) REFERENCES client_projects(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS project_tasks (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,project_id BIGINT UNSIGNED NOT NULL,milestone_id BIGINT UNSIGNED NULL,title VARCHAR(255) NOT NULL,description TEXT NULL,status ENUM('todo','in_progress','review','completed','cancelled') NOT NULL DEFAULT 'todo',priority ENUM('low','normal','high','urgent') NOT NULL DEFAULT 'normal',assigned_to BIGINT UNSIGNED NULL,due_date DATE NULL,completed_at DATETIME NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,INDEX(project_id),INDEX(milestone_id),INDEX(status),CONSTRAINT fk_task_project FOREIGN KEY(project_id) REFERENCES client_projects(id) ON DELETE CASCADE,CONSTRAINT fk_task_milestone FOREIGN KEY(milestone_id) REFERENCES project_milestones(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS project_documents (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,project_id BIGINT UNSIGNED NOT NULL,title VARCHAR(255) NOT NULL,file_path VARCHAR(500) NOT NULL,file_name VARCHAR(255) NOT NULL,mime_type VARCHAR(120) NULL,file_size BIGINT UNSIGNED NULL,visibility ENUM('admin','client') NOT NULL DEFAULT 'client',uploaded_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(project_id),CONSTRAINT fk_document_project FOREIGN KEY(project_id) REFERENCES client_projects(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS project_approvals (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,project_id BIGINT UNSIGNED NOT NULL,milestone_id BIGINT UNSIGNED NULL,approval_type ENUM('milestone','final','design','content','other') NOT NULL DEFAULT 'milestone',status ENUM('pending','approved','rejected') NOT NULL DEFAULT 'pending',comment TEXT NULL,approved_by VARCHAR(180) NULL,approved_at DATETIME NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(project_id),CONSTRAINT fk_approval_project FOREIGN KEY(project_id) REFERENCES client_projects(id) ON DELETE CASCADE,CONSTRAINT fk_approval_milestone FOREIGN KEY(milestone_id) REFERENCES project_milestones(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
